function showAppNotice(message) {
  const notice = document.getElementById('appNotice');
  if (!notice) return;
  notice.textContent = String(message || 'Something went wrong.');
  notice.classList.remove('hidden');
}

function clearAppNotice() {
  const notice = document.getElementById('appNotice');
  if (!notice) return;
  notice.textContent = '';
  notice.classList.add('hidden');
}

function updateWorkspaceDisplay() {
  const currentWs = (state.workspaces || []).find(
    w => w.WorkspaceID === state.currentWorkspace
  );
  const label = currentWs
    ? String(currentWs.WorkspaceName || currentWs.WorkspaceID)
    : String(state.currentWorkspace || '-');
  const badge = document.getElementById('currentWorkspaceBadge');
  const timerLabel = document.getElementById('userActiveWsName');
  if (badge) badge.textContent = label;
  if (timerLabel) timerLabel.textContent = label;
}

function renderUserWorkspaceControl() {
  const select = document.getElementById('userWorkspaceSelect');
  const badge = document.getElementById('currentWorkspaceBadge');
  if (!select || !badge) return;

  select.replaceChildren();
  (state.workspaces || []).forEach(ws => {
    select.add(new Option(
      String(ws.WorkspaceName || ws.WorkspaceID),
      String(ws.WorkspaceID)
    ));
  });
  select.value = state.currentWorkspace || '';

  if ((state.workspaces || []).length > 1) {
    select.classList.remove('hidden');
    badge.classList.add('hidden');
  } else {
    select.classList.add('hidden');
    badge.classList.remove('hidden');
  }
}

async function changeUserWorkspace(workspaceId) {
  const select = document.getElementById('userWorkspaceSelect');
  if (!workspaceId || workspaceId === state.currentWorkspace) return;

  if (state.activeTimer) {
    if (select) select.value = state.currentWorkspace;
    alert('Stop your active timer before switching workspaces.');
    return;
  }

  if (!(state.workspaces || []).some(ws => ws.WorkspaceID === workspaceId)) {
    if (select) select.value = state.currentWorkspace;
    showAppNotice('That workspace is not assigned to your account.');
    return;
  }

  state.currentWorkspace = workspaceId;
  updateWorkspaceDisplay();
  clearAppNotice();

  await loadWorkspaceData();
  await recoverActiveTimer();
  await loadRecentEntries();

  if (!document.getElementById('timesheetView').classList.contains('hidden')) {
    await loadTimesheet();
    await loadMyTimeHistory();
  }
  if (!document.getElementById('reportsView').classList.contains('hidden')) {
    await loadReportsView();

